<script setup>
import {onMounted,ref,computed} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import NodeFacts from '../components/NodeFacts.vue'
import {api} from '../lib/api.js'
import {activeTheme} from '../lib/theme.js'
const nodes=ref([]),groups=ref([]),credentials=ref([]),search=ref(''),groupName=ref(''),memberGroup=ref(''),formOpen=ref(false),detailOpen=ref(false),selected=ref(null),error=ref(''),message=ref(''),busy=ref(false),form=ref({hostname:'',fqdn:'',ip:'',credentialIds:[]})
const retrainDays=ref(7),trainingDays=ref(30)
const rulePage=ref(null),rulesLoading=ref(false),rulesError=ref('')
const filtered=computed(()=>nodes.value.filter(n=>[n.hostname,n.fqdn,n.ip].join(' ').toLowerCase().includes(search.value.toLowerCase())))
async function load(){try{const [loadedNodes,loadedCredentials,loadedGroups,settings]=await Promise.all([api('/nodes'),api('/credentials'),api('/node-groups'),api('/settings/training')]);nodes.value=loadedNodes;credentials.value=loadedCredentials;groups.value=loadedGroups;trainingDays.value=settings.newHostTrainingDays}catch(e){error.value=e.message}}
onMounted(load)
async function create(){busy.value=true;error.value='';try{const node=await api('/nodes',{method:'POST',body:form.value});formOpen.value=false;form.value={hostname:'',fqdn:'',ip:'',credentialIds:[]};message.value=`${node.hostname} added; ${node.training.days}-day training started`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function select(node){selected.value=await api(`/nodes/${node.id}`);detailOpen.value=true;rulePage.value=null;rulesError.value='';if(['winrm','winrms'].includes(selected.value.transport))loadRules(0)}
async function loadRules(offset=0){if(!selected.value)return;rulesLoading.value=true;rulesError.value='';try{rulePage.value=await api(`/nodes/${selected.value.id}/firewall-rules?offset=${offset}&limit=100`)}catch(e){rulesError.value=e.message}finally{rulesLoading.value=false}}
async function action(name){busy.value=true;error.value='';try{const result=await api(`/nodes/${selected.value.id}/${name}`,{method:'POST',body:{}});selected.value=await api(`/nodes/${selected.value.id}`);if(name==='probe')selected.value.probe=result;if(['winrm','winrms'].includes(selected.value.transport))loadRules(0);await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function createGroup(){try{await api('/node-groups',{method:'POST',body:{name:groupName.value}});groupName.value='';message.value='Node group created';await load()}catch(e){error.value=e.message}}
async function addToGroup(){if(!selected.value||!memberGroup.value)return;try{await api(`/node-groups/${memberGroup.value}/members`,{method:'POST',body:{nodeId:selected.value.id}});message.value=`${selected.value.hostname} added to group`;memberGroup.value='';await load()}catch(e){error.value=e.message}}
async function retrain(){if(!selected.value)return;busy.value=true;error.value='';try{const session=await api(`/nodes/${selected.value.id}/training`,{method:'POST',body:{durationDays:Number(retrainDays.value)}});selected.value=await api(`/nodes/${selected.value.id}`);message.value=`Relearning started through ${new Date(session.endsAt).toLocaleString()}`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="view"><PageHeader eyebrow="ASSETS / WINDOWS NODES" :title="activeTheme==='enterprise'?'Monitored assets':'Node inventory'" description="Onboard, inspect and verify firewall hosts"><button class="button primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> Add node</button></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">MANAGED ASSETS</span><h2>{{nodes.length}} nodes</h2></div><div class="table-tools"><input v-model="search" class="search" placeholder="Search hostname or address" aria-label="Search nodes"><button class="icon-button" @click="load" title="Refresh"><i class="mdi mdi-refresh"></i></button></div></div><div class="table-wrap"><table><thead><tr><th>HOSTNAME</th><th>ADDRESS</th><th>OS</th><th>MODE</th><th>SOURCE</th><th>FIREWALL</th><th>VERIFY</th><th>STATUS</th><th>LAST SEEN</th><th></th></tr></thead><tbody><tr v-for="node in filtered" :key="node.id" @click="select(node)" class="click-row"><td><i class="mdi mdi-monitor"></i> <strong>{{node.hostname}}</strong></td><td class="mono">{{node.ip||node.fqdn||'—'}}</td><td>{{node.os_version||'Unknown'}}</td><td>{{node.connection_mode}}</td><td><span class="status" :class="node.ad_missing?'failed':node.ad_guid?'reachable':'unknown'">{{node.ad_missing?'AD missing':node.inventory_source||'manual'}}</span></td><td><span class="status" :class="node.firewall_state">{{node.firewall_state}}</span></td><td><span class="status" :class="node.verification?.status||'unknown'">{{node.verification?.status||'Unchecked'}}</span></td><td><span class="status" :class="node.status">{{node.status}}</span></td><td>{{node.last_seen_at?new Date(node.last_seen_at).toLocaleString():'Never'}}</td><td><i class="mdi mdi-chevron-right"></i></td></tr><tr v-if="!filtered.length"><td colspan="10" class="empty-table">{{nodes.length?'No nodes match your search.':'No nodes yet. Add a Windows host to begin.'}}</td></tr></tbody></table></div></section><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">FLEET ORGANIZATION</span><h2>Node groups</h2></div></div><div v-for="group in groups" :key="group.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-server-network"></i></div><strong>{{group.name}}</strong></div><div v-if="!groups.length" class="empty-side">No node groups yet.</div><form class="inline-form" @submit.prevent="createGroup"><input v-model="groupName" required placeholder="New node group" aria-label="New node group"><button class="button small secondary">Create group</button></form></section><GlassWindow v-model="formOpen" title="Add Windows node"><form class="form-grid" @submit.prevent="create"><label>Hostname<input v-model="form.hostname" required placeholder="server-01"></label><label>FQDN<input v-model="form.fqdn" placeholder="server-01.example.com"></label><label>IP address<input v-model="form.ip" placeholder="10.0.0.5"></label><p class="training-note">New hosts train automatically for {{trainingDays}} days before learned rules are applied.</p><label>Credential<select v-model="form.credentialIds[0]"><option :value="undefined">Select credential</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><div class="form-actions"><button type="button" class="button secondary" @click="formOpen=false">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Adding…':'Add node'}}</button></div></form></GlassWindow><GlassWindow v-model="detailOpen" :title="selected?.hostname||'Node details'" width="760px"><template v-if="selected"><div class="detail-grid"><div><span>STATUS</span><strong>{{selected.status}}</strong></div><div><span>TRANSPORT</span><strong>{{selected.transport||'Not probed'}}</strong></div><div><span>ADDRESS</span><strong>{{selected.ip||selected.fqdn||'—'}}</strong></div><div><span>OS BUILD</span><strong>{{selected.os_build||'Unknown'}}</strong></div><div><span>FIREWALL STATE</span><strong>{{selected.firewall_state}}</strong></div><div><span>LAST VERIFY</span><strong :class="selected.verification?.status==='fail'?'danger-text':''">{{selected.verification?.status||'Unchecked'}}</strong></div><div><span>TRAINING ENDS</span><strong>{{selected.training?.status==='active'?new Date(selected.training.ends_at).toLocaleString():'—'}}</strong></div></div><div class="inline-actions"><button class="button secondary" :disabled="busy" @click="action('probe')"><i class="mdi mdi-lan-check"></i> Probe</button><button class="button secondary" :disabled="busy" @click="action('facts/refresh')"><i class="mdi mdi-refresh"></i> Collect facts</button><button class="button secondary" :disabled="busy" @click="action('dns/refresh')"><i class="mdi mdi-dns"></i> Refresh DNS</button></div><div class="training-control"><div><span class="eyebrow">HOST TRAINING</span><strong>{{selected.training?.mode==='auto'?'Automatic':selected.training?.mode==='manual'?'Manual review':'No session'}} · {{selected.training?.status||'none'}}</strong><small v-if="selected.training?.last_error">{{selected.training.last_error}}</small></div><form v-if="!['active','review','applying','apply-failed'].includes(selected.training?.status)" class="training-restart" @submit.prevent="retrain"><label>Relearn for <input v-model.number="retrainDays" type="number" min="1" max="365" required> days</label><button class="button small secondary" :disabled="busy">Start relearning</button></form><router-link v-else-if="selected.training?.status==='apply-failed'" class="button small secondary" to="/logs">Retry in Logs</router-link></div><div class="inline-form"><select v-model="memberGroup" aria-label="Node group"><option value="">Select group</option><option v-for="group in groups" :key="group.id" :value="group.id">{{group.name}}</option></select><button class="button small secondary" :disabled="!memberGroup" @click="addToGroup">Add to group</button></div><div v-if="selected.probe" class="code-block">{{JSON.stringify(selected.probe,null,2)}}</div><NodeFacts :node="selected" :rule-page="rulePage" :rules-loading="rulesLoading" :rules-error="rulesError" @rules-page="loadRules"/><h3>DNS</h3><pre class="code-block">{{JSON.stringify(selected.dns||{},null,2)}}</pre></template></GlassWindow></div></template>
